const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const kornwerderzand = ee.Geometry.Point([5.339, 53.071]).buffer(500); // Near Kornwerderzand
  const afsluitdijk = ee.Geometry.Point([5.178, 53.027]).buffer(500); // Near Afsluitdijk

  const date = '2023-07-08';

  // 2. Data Acquisition
  let s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filterBounds(ee.Geometry.Point([5.258, 53.049])) // Center of area
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  let imageCount = s2.size().getInfo();
  console.log(`Sentinel-2 images on ${date}: ${imageCount}`);

  if (imageCount === 0) {
    console.log("No images found for exact date, trying ±3 days");
    s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterDate('2023-07-05', '2023-07-11')
      .filterBounds(ee.Geometry.Point([5.258, 53.049]))
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

    imageCount = s2.size().getInfo();
    console.log(`Sentinel-2 images in ±3 day window: ${imageCount}`);

    if (imageCount === 0) {
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // Get best image (least cloudy)
  const image = s2.sort('CLOUDY_PIXEL_PERCENTAGE').first();

  // 3. Processing - Calculate NDVI for greenness
  const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');

  // 4. Extract values for both locations
  const kornwerderzandStats = ndvi.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: kornwerderzand,
    scale: 100,
    maxPixels: 1e9
  });

  const afsluitdijkStats = ndvi.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: afsluitdijk,
    scale: 100,
    maxPixels: 1e9
  });

  const kornData = kornwerderzandStats.getInfo();
  const afslData = afsluitdijkStats.getInfo();

  console.log(`Kornwerderzand - NDVI: ${kornData.NDVI_mean?.toFixed(4)}, Pixels: ${kornData.NDVI_count}`);
  console.log(`Afsluitdijk - NDVI: ${afslData.NDVI_mean?.toFixed(4)}, Pixels: ${afslData.NDVI_count}`);

  // 5. Validation & Final Answer
  if (kornData.NDVI_count === 0 || afslData.NDVI_count === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (kornData.NDVI_mean === null || afslData.NDVI_mean === null || 
      isNaN(kornData.NDVI_mean) || isNaN(afslData.NDVI_mean)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare NDVI values - higher NDVI means greener
  if (kornData.NDVI_mean > afslData.NDVI_mean) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
